// orders from remote clients must reject per order, never lose the tick.
const EXCLUSIVE = [{"members":[{"action":"strike","key":["A",null]}]}];

/** FNV-1a, matching the generator's — the staleness check below. */
function hash(text) {
  let h = 0x811c9dc5;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i) & 0xff;
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h.toString(16).padStart(8, '0');
}

